typedef float vm_num_t;

class vm_stack
{
public:
  bool push(const char *src, int n);
};

class script_library_class
{
public:
  class function
  {
  public:
    enum entry_t
    {
      FIRST_ENTRY,
      RECALL_ENTRY
    };

    virtual bool operator()(vm_stack &stack, entry_t entry) { return true; }
  };
};

struct sys_time_stuct
{
  short year;
  short month;
  short weekday;
  short day;
  short hour;
  short minute;
  short second;
};

class game
{
public:
  const sys_time_stuct &get_systime() const { return systime; }

private:
  sys_time_stuct systime;
};

extern game *g_game_ptr;
void error(const char *);

class slf_systime_minute_t : public script_library_class::function
{
public:
  virtual bool operator()(vm_stack &stack, entry_t entry);
};

bool slf_systime_minute_t::operator()(vm_stack &stack, entry_t entry)
{
  vm_num_t result = g_game_ptr->get_systime().minute;

  if (!stack.push((char *)&result, sizeof(result)))
    error("script stack overflow");
  return true;
}
